function splitRecords(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'normalize' && mode !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
  }

  const records = splitRecords(readStdin())
  const results = []

  for (let index = 0; index < records.length; index += 1) {
    const record = records[index]
    const number = index + 1
    try {
      if (mode === 'normalize') {
        results.push(normalize(record))
      } else {
        const space = record.indexOf(' ')
        if (space === -1) fail(`line ${number}: expected a base and a reference`)
        const base = record.slice(0, space)
        const reference = record.slice(space + 1)
        if (parse(base).scheme === null) fail(`line ${number}: the base has no scheme`)
        results.push(resolve(base, reference))
      }
    } catch (error) {
      if (error instanceof UriError) fail(`line ${number}: ${error.message}`)
      throw error
    }
  }

  process.stdout.write(results.map((line) => `${line}\n`).join(''))
}

main(process.argv.slice(2))
